","/**
 * Conversation Engine — State machine for the Customer Assistant chatbot.
 * Manages conversation flows: complaint, track, refund, contact.
 */

// Extend Window to declare g_ck
declare global {
 interface Window {
 g_ck: string;
 }
}

// --- Types ---

export interface Message {
 id: string;
 role: 'user' | 'assistant';
 text: string;
 timestamp: Date;
 chips?: string[];
 actionCards?: ActionCard[];
 confirmation?: ConfirmationData;
}

export interface ActionCard {
 id: string;
 title: string;
 description: string;
 icon: string;
}

export interface ConfirmationData {
 caseNumber: string;
 category: string;
 orderNumber: string;
 description: string;
 status: string;
}

export interface ComplaintData {
 category: string;
 orderNumber: string;
 description: string;
 photoProvided: boolean;
}

export interface EngineResponse {
 messages: Message[];
 needsSubmission?: boolean;
 complaintData?: ComplaintData;
}

type FlowState =
 | 'idle'
 | 'complaint_category'
 | 'complaint_order'
 | 'complaint_description'
 | 'complaint_photo'
 | 'track_order_number'
 | 'refund_order_number'
 | 'refund_reason'
 | 'contact_topic';

// --- Category Mapping ---

const CATEGORY_MAP: Record<string, string> = {
 'Missing Item': 'missing_items',
 'Damaged Item': 'damaged_items',
 'Wrong Product': 'wrong_items',
 'Delivery Delay': 'late_delivery',
 'Payment Issue': 'overcharge',
 'Other': 'other',
};

const COMPLAINT_CATEGORIES = [
 'Missing Item',
 'Damaged Item',
 'Wrong Product',
 'Delivery Delay',
 'Payment Issue',
 'Other',
];

// --- Engine Class ---

export class ConversationEngine {
 private state: FlowState = 'idle';
 private complaintData: Partial<ComplaintData> = {};
 private messageIdCounter = 0;

 private generateId(): string {
 this.messageIdCounter++;
 return `msg-${Date.now()}-${this.messageIdCounter}`;
 }

 private createAssistantMessage(
 text: string,
 options?: { chips?: string[]; actionCards?: ActionCard[]; confirmation?: ConfirmationData }
 ): Message {
 return {
 id: this.generateId(),
 role: 'assistant',
 text,
 timestamp: new Date(),
 ...(options || {}),
 };
 }

 public getWelcomeMessages(): Message[] {
 return [
 this.createAssistantMessage(
 "Hello! I'm your Customer Assistant. How can I help you today?",
 {
 actionCards: [
 {
 id: 'complaint',
 title: 'File a Complaint',
 description: 'Report an issue with your order',
 icon: '⚠️',
 },
 {
 id: 'track',
 title: 'Track Order',
 description: 'Check the status of your delivery',
 icon: '📦',
 },
 {
 id: 'refund',
 title: 'Request Refund',
 description: 'Initiate a refund for your order',
 icon: '💰',
 },
 {
 id: 'contact',
 title: 'Contact Support',
 description: 'Speak with a support agent',
 icon: '💬',
 },
 ],
 }
 ),
 ];
 }

 public processInput(input: string): EngineResponse {
 switch (this.state) {
 case 'idle':
 return this.handleIdle(input);
 case 'complaint_category':
 return this.handleComplaintCategory(input);
 case 'complaint_order':
 return this.handleComplaintOrder(input);
 case 'complaint_description':
 return this.handleComplaintDescription(input);
 case 'complaint_photo':
 return this.handleComplaintPhoto(input);
 case 'track_order_number':
 return this.handleTrackOrder(input);
 case 'refund_order_number':
 return this.handleRefundOrder(input);
 case 'refund_reason':
 return this.handleRefundReason(input);
 case 'contact_topic':
 return this.handleContactTopic(input);
 default:
 return { messages: [this.createAssistantMessage("I'm not sure what you mean. Let me start over.")] };
 }
 }

 // --- Idle / Flow Selection ---

 private handleIdle(input: string): EngineResponse {
 const lower = input.toLowerCase();

 if (lower.includes('complaint') || lower.includes('file') || lower.includes('report') || input === 'complaint') {
 return this.startComplaintFlow();
 }
 if (lower.includes('track') || lower.includes('order status') || lower.includes('delivery') || input === 'track') {
 return this.startTrackFlow();
 }
 if (lower.includes('refund') || lower.includes('money back') || input === 'refund') {
 return this.startRefundFlow();
 }
 if (lower.includes('contact') || lower.includes('support') || lower.includes('agent') || input === 'contact') {
 return this.startContactFlow();
 }

 return {
 messages: [
 this.createAssistantMessage(
 "I'd be happy to help! Please select one of the options below, or describe what you need.",
 {
 actionCards: [
 { id: 'complaint', title: 'File a Complaint', description: 'Report an issue with your order', icon: '⚠️' },
 { id: 'track', title: 'Track Order', description: 'Check the status of your delivery', icon: '📦' },
 { id: 'refund', title: 'Request Refund', description: 'Initiate a refund for your order', icon: '💰' },
 { id: 'contact', title: 'Contact Support', description: 'Speak with a support agent', icon: '💬' },
 ],
 }
 ),
 ],
 };
 }

 // --- Complaint Flow ---

 private startComplaintFlow(): EngineResponse {
 this.state = 'complaint_category';
 this.complaintData = {};
 return {
 messages: [
 this.createAssistantMessage(
 "I'm sorry to hear you're having an issue. Let's get this resolved.\n\nWhat category best describes your complaint?",
 { chips: COMPLAINT_CATEGORIES }
 ),
 ],
 };
 }

 private handleComplaintCategory(input: string): EngineResponse {
 const matched = COMPLAINT_CATEGORIES.find(
 (c) => c.toLowerCase() === input.toLowerCase()
 );
 this.complaintData.category = matched || input;
 this.state = 'complaint_order';

 return {
 messages: [
 this.createAssistantMessage(
 `Got it — "${this.complaintData.category}". Please provide your order number so I can look it up.`
 ),
 ],
 };
 }

 private handleComplaintOrder(input: string): EngineResponse {
 this.complaintData.orderNumber = input.trim();
 this.state = 'complaint_description';

 return {
 messages: [
 this.createAssistantMessage(
 `Order **${this.complaintData.orderNumber}** noted. Please describe the issue in detail — what happened, when, and any other relevant info.`
 ),
 ],
 };
 }

 private handleComplaintDescription(input: string): EngineResponse {
 this.complaintData.description = input.trim();
 this.state = 'complaint_photo';

 return {
 messages: [
 this.createAssistantMessage(
 'Thank you for the details. Would you like to attach a photo as evidence? (Yes/No)',
 { chips: ['Yes', 'No'] }
 ),
 ],
 };
 }

 private handleComplaintPhoto(input: string): EngineResponse {
 const wantsPhoto = input.toLowerCase().startsWith('y');
 this.complaintData.photoProvided = wantsPhoto;
 this.state = 'idle';

 // Instead of generating a fake ID, signal that submission is needed
 const data: ComplaintData = {
 category: this.complaintData.category || 'Other',
 orderNumber: this.complaintData.orderNumber || 'Unknown',
 description: this.complaintData.description || '',
 photoProvided: wantsPhoto,
 };

 return {
 needsSubmission: true,
 complaintData: data,
 messages: [
 this.createAssistantMessage(
 'Submitting your complaint...'
 ),
 ],
 };
 }

 // --- Track Order Flow ---

 private startTrackFlow(): EngineResponse {
 this.state = 'track_order_number';
 return {
 messages: [
 this.createAssistantMessage('Sure! Please provide your order number and I\'ll check the status.'),
 ],
 };
 }

 private handleTrackOrder(input: string): EngineResponse {
 const orderNum = input.trim();
 this.state = 'idle';

 return {
 messages: [
 this.createAssistantMessage(
 `📦 **Order ${orderNum} Status**\n\n` +
 `• **Status:** In Transit\n` +
 `• **Estimated Delivery:** 2-3 business days\n` +
 `• **Last Update:** Package left distribution center\n\n` +
 `You'll receive a notification when it's out for delivery. Is there anything else I can help with?`,
 {
 actionCards: [
 { id: 'complaint', title: 'File a Complaint', description: 'Report an issue', icon: '⚠️' },
 { id: 'contact', title: 'Contact Support', description: 'Speak with an agent', icon: '💬' },
 ],
 }
 ),
 ],
 };
 }

 // --- Refund Flow ---

 private startRefundFlow(): EngineResponse {
 this.state = 'refund_order_number';
 return {
 messages: [
 this.createAssistantMessage('I can help with a refund request. Please provide the order number for the item you\'d like refunded.'),
 ],
 };
 }

 private handleRefundOrder(input: string): EngineResponse {
 this.state = 'refund_reason';
 return {
 messages: [
 this.createAssistantMessage(
 `Order **${input.trim()}** found. What's the reason for your refund request?`,
 {
 chips: [
 'Item not received',
 'Item damaged',
 'Wrong item sent',
 'Changed my mind',
 'Other',
 ],
 }
 ),
 ],
 };
 }

 private handleRefundReason(input: string): EngineResponse {
 this.state = 'idle';
 return {
 messages: [
 this.createAssistantMessage(
 `✅ **Refund Request Submitted**\n\n` +
 `• **Reason:** ${input}\n` +
 `• **Expected Processing:** 5-7 business days\n` +
 `• **Refund Method:** Original payment method\n\n` +
 `You'll receive an email confirmation shortly. Is there anything else I can help with?`,
 {
 actionCards: [
 { id: 'track', title: 'Track Order', description: 'Check another order', icon: '📦' },
 { id: 'contact', title: 'Contact Support', description: 'Speak with an agent', icon: '💬' },
 ],
 }
 ),
 ],
 };
 }

 // --- Contact Flow ---

 private startContactFlow(): EngineResponse {
 this.state = 'contact_topic';
 return {
 messages: [
 this.createAssistantMessage(
 'I\'ll connect you with a support agent. To help route you to the right team, what topic do you need help with?',
 {
 chips: [
 'Order Issue',
 'Account Problem',
 'Technical Support',
 'Billing Question',
 'General Inquiry',
 ],
 }
 ),
 ],
 };
 }

 private handleContactTopic(input: string): EngineResponse {
 this.state = 'idle';
 return {
 messages: [
 this.createAssistantMessage(
 `🔗 **Connecting to Support**\n\n` +
 `• **Topic:** ${input}\n` +
 `• **Estimated Wait:** Under 2 minutes\n` +
 `• **Queue Position:** 1\n\n` +
 `A support agent will be with you shortly. In the meantime, is there anything else I can assist with?`,
 {
 actionCards: [
 { id: 'complaint', title: 'File a Complaint', description: 'Report an issue', icon: '⚠️' },
 { id: 'track', title: 'Track Order', description: 'Check order status', icon: '📦' },
 ],
 }
 ),
 ],
 };
 }

 public reset(): void {
 this.state = 'idle';
 this.complaintData = {};
 }
}

// --- API Submission Function ---

export async function submitComplaintToServiceNow(data: {
 category: string;
 orderNumber: string;
 description: string;
}): Promise<{ success: boolean; caseNumber?: string; error?: string }> {
 const categoryValue = CATEGORY_MAP[data.category] || 'other';

 const body = {
 short_description: `Customer complaint: ${data.category} - Order ${data.orderNumber}`,
 x_2145749_qc_complaint_type: categoryValue,
 x_2145749_qc_order_number: data.orderNumber,
 description: data.description,
 };

 try {
 const response = await fetch('/api/now/table/sn_customerservice_case', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Accept': 'application/json',
 'X-UserToken': window.g_ck,
 },
 body: JSON.stringify(body),
 });

 if (!response.ok) {
 const errorText = await response.text();
 return {
 success: false,
 error: `API returned ${response.status}: ${errorText}`,
 };
 }

 const result = await response.json();
 const caseNumber = result?.result?.number;

 if (!caseNumber) {
 return {
 success: false,
 error: 'Case was created but no case number was returned.',
 };
 }

 return { success: true, caseNumber };
 } catch (err: unknown) {
 const errorMessage = err instanceof Error ? err.message : 'Unknown network error';
 return { success: false, error: errorMessage };
 }
}
","/**
 * AssistantApp — Main React component for the Customer Assistant chatbot UI.
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import {
 ConversationEngine,
 submitComplaintToServiceNow,
 Message,
 ActionCard,
 EngineResponse,
 ConfirmationData,
} from './conversationEngine';
import './assistant.css';

// --- Helper: simple markdown-like bold rendering ---
function renderText(text: string): React.ReactNode[] {
 const parts = text.split(/(\*\*[^*]+\*\*)/g);
 return parts.map((part, i) => {
 if (part.startsWith('**') && part.endsWith('**')) {
 return <strong key={i}>{part.slice(2, -2)}</strong>;
 }
 return <span key={i}>{part}</span>;
 });
}

function renderMessageText(text: string): React.ReactNode {
 const lines = text.split('\n');
 return (
 <>
 {lines.map((line, i) => (
 <React.Fragment key={i}>
 {renderText(line)}
 {i < lines.length - 1 && <br />}
 </React.Fragment>
 ))}
 </>
 );
}

// --- Typing Indicator ---
function TypingIndicator(): React.ReactElement {
 return (
 <div className="typing-indicator">
 <span className="dot"></span>
 <span className="dot"></span>
 <span className="dot"></span>
 </div>
 );
}

// --- Main Component ---
export function AssistantApp(): React.ReactElement {
 const [messages, setMessages] = useState<Message[]>([]);
 const [inputValue, setInputValue] = useState('');
 const [isTyping, setIsTyping] = useState(false);
 const [isSubmitting, setIsSubmitting] = useState(false);

 const engineRef = useRef<ConversationEngine>(new ConversationEngine());
 const messagesEndRef = useRef<HTMLDivElement>(null);
 const inputRef = useRef<HTMLInputElement>(null);

 // Initialize welcome messages
 useEffect(() => {
 const welcome = engineRef.current.getWelcomeMessages();
 setMessages(welcome);
 }, []);

 // Auto-scroll to bottom
 useEffect(() => {
 messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
 }, [messages, isTyping]);

 // Focus input
 useEffect(() => {
 inputRef.current?.focus();
 }, [messages]);

 const addUserMessage = useCallback((text: string): Message => {
 const msg: Message = {
 id: `user-${Date.now()}`,
 role: 'user',
 text,
 timestamp: new Date(),
 };
 setMessages((prev) => [...prev, msg]);
 return msg;
 }, []);

 const addAssistantMessages = useCallback((msgs: Message[]) => {
 setMessages((prev) => [...prev, ...msgs]);
 }, []);

 const handleSubmit = useCallback(
 async (text: string) => {
 if (!text.trim() || isSubmitting) return;

 addUserMessage(text);
 setInputValue('');
 setIsTyping(true);

 // Small delay for natural feel
 await new Promise((r) => setTimeout(r, 600));

 const response: EngineResponse = engineRef.current.processInput(text);
 setIsTyping(false);

 if (response.needsSubmission && response.complaintData) {
 // Show the "submitting" message
 addAssistantMessages(response.messages);
 setIsSubmitting(true);

 // Make the real API call
 const result = await submitComplaintToServiceNow({
 category: response.complaintData.category,
 orderNumber: response.complaintData.orderNumber,
 description: response.complaintData.description,
 });

 setIsSubmitting(false);

 if (result.success && result.caseNumber) {
 // Success — show real case number
 const confirmationMsg: Message = {
 id: `confirm-${Date.now()}`,
 role: 'assistant',
 text:
 `✅ **Complaint Confirmation**\n\n` +
 `Your complaint has been filed and a case has been created.\n\n` +
 `• **Case Number:** ${result.caseNumber}\n` +
 `• **Category:** ${response.complaintData.category}\n` +
 `• **Order:** ${response.complaintData.orderNumber}\n` +
 `• **Status:** Open — Under Review\n\n` +
 `Our team will investigate and respond within 24-48 hours. You can track this case using the case number above.`,
 timestamp: new Date(),
 confirmation: {
 caseNumber: result.caseNumber,
 category: response.complaintData.category,
 orderNumber: response.complaintData.orderNumber,
 description: response.complaintData.description,
 status: 'Open — Under Review',
 },
 };
 addAssistantMessages([confirmationMsg]);
 } else {
 // Error — show error but don't crash
 const errorMsg: Message = {
 id: `error-${Date.now()}`,
 role: 'assistant',
 text:
 `❌ **Submission Error**\n\n` +
 `We encountered an issue while filing your complaint:\n` +
 `${result.error || 'Unknown error'}\n\n` +
 `Please try again or contact support directly. Your complaint details have been saved locally.`,
 timestamp: new Date(),
 };
 addAssistantMessages([errorMsg]);
 }
 } else {
 // Normal response — just show messages
 addAssistantMessages(response.messages);
 }
 },
 [isSubmitting, addUserMessage, addAssistantMessages]
 );

 const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
 if (e.key === 'Enter' && !e.shiftKey) {
 e.preventDefault();
 handleSubmit(inputValue);
 }
 };

 const handleChipClick = (chip: string) => {
 handleSubmit(chip);
 };

 const handleActionCardClick = (card: ActionCard) => {
 handleSubmit(card.id);
 };

 return (
 <div className="assistant-container">
 {/* Header */}
 <header className="assistant-header">
 <div className="header-left">
 <div className="ai-avatar">
 <span className="avatar-icon">◆</span>
 </div>
 <div className="header-text">
 <h1 className="brand-name">DarkOps AI</h1>
 <p className="brand-subtitle">Customer Assistant</p>
 </div>
 </div>
 <div className="header-right">
 <span className="status-dot"></span>
 <span className="status-text">Online</span>
 </div>
 </header>

 {/* Messages Area */}
 <main className="messages-area">
 {messages.map((msg) => (
 <div key={msg.id} className={`message-row ${msg.role}`}>
 {msg.role === 'assistant' && (
 <div className="message-avatar">
 <span>◆</span>
 </div>
 )}
 <div className={`message-bubble ${msg.role}`}>
 <div className="message-text">{renderMessageText(msg.text)}</div>

 {/* Confirmation Card */}
 {msg.confirmation && (
 <div className="confirmation-card">
 <div className="confirmation-badge">
 <span className="badge-icon">✓</span>
 <span className="badge-text">{msg.confirmation.caseNumber}</span>
 </div>
 </div>
 )}

 {/* Chips */}
 {msg.chips && msg.chips.length > 0 && (
 <div className="chips-container">
 {msg.chips.map((chip) => (
 <button
 key={chip}
 className="chip"
 onClick={() => handleChipClick(chip)}
 >
 {chip}
 </button>
 ))}
 </div>
 )}

 {/* Action Cards */}
 {msg.actionCards && msg.actionCards.length > 0 && (
 <div className="action-cards-container">
 {msg.actionCards.map((card) => (
 <button
 key={card.id}
 className="action-card"
 onClick={() => handleActionCardClick(card)}
 >
 <span className="action-card-icon">{card.icon}</span>
 <div className="action-card-content">
 <span className="action-card-title">{card.title}</span>
 <span className="action-card-desc">{card.description}</span>
 </div>
 </button>
 ))}
 </div>
 )}
 </div>
 </div>
 ))}

 {/* Typing Indicator */}
 {isTyping && (
 <div className="message-row assistant">
 <div className="message-avatar">
 <span>◆</span>
 </div>
 <div className="message-bubble assistant">
 <TypingIndicator />
 </div>
 </div>
 )}

 {/* Submitting Indicator */}
 {isSubmitting && (
 <div className="message-row assistant">
 <div className="message-avatar">
 <span>◆</span>
 </div>
 <div className="message-bubble assistant">
 <div className="submitting-indicator">
 <div className="spinner"></div>
 <span>Creating case in ServiceNow...</span>
 </div>
 </div>
 </div>
 )}

 <div ref={messagesEndRef} />
 </main>

 {/* Input Bar */}
 <footer className="input-bar">
 <div className="input-wrapper">
 <input
 ref={inputRef}
 type="text"
 className="message-input"
 placeholder="Type your message..."
 value={inputValue}
 onChange={(e) => setInputValue(e.target.value)}
 onKeyDown={handleKeyDown}
 disabled={isSubmitting}
 />
 <button
 className="send-button"
 onClick={() => handleSubmit(inputValue)}
 disabled={!inputValue.trim() || isSubmitting}
 >
 <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
 <path
 d="M22 2L11 13"
 stroke="currentColor"
 strokeWidth="2"
 strokeLinecap="round"
 strokeLinejoin="round"
 />
 <path
 d="M22 2L15 22L11 13L2 9L22 2Z"
 stroke="currentColor"
 strokeWidth="2"
 strokeLinecap="round"
 strokeLinejoin="round"
 />
 </svg>
 </button>
 </div>
 </footer>
 </div>
 );
}
","/**
 * assistant.css — Dark theme styles for the Customer Assistant chatbot.
 * Background: #0a0e14 (matches page inline style)
 * Accent: #06b6d4 (cyan/teal)
 */

/* === Reset & Base === */
* {
 margin: 0;
 padding: 0;
 box-sizing: border-box;
}

html, body {
 height: 100%;
 overflow: hidden;
 background: #0a0e14;
 font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
 color: #e2e8f0;
 font-size: 14px;
 line-height: 1.5;
}

/* === Container === */
.assistant-container {
 display: flex;
 flex-direction: column;
 height: 100vh;
 max-width: 900px;
 margin: 0 auto;
 background: #0a0e14;
}

/* === Header === */
.assistant-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 16px 24px;
 background: #0d1117;
 border-bottom: 1px solid #1e293b;
 flex-shrink: 0;
}

.header-left {
 display: flex;
 align-items: center;
 gap: 12px;
}

.ai-avatar {
 width: 40px;
 height: 40px;
 border-radius: 10px;
 background: linear-gradient(135deg, #06b6d4, #0891b2);
 display: flex;
 align-items: center;
 justify-content: center;
 box-shadow: 0 0 20px rgba(6, 182, 212, 0.3);
}

.avatar-icon {
 color: #ffffff;
 font-size: 18px;
 font-weight: bold;
}

.header-text {
 display: flex;
 flex-direction: column;
}

.brand-name {
 font-size: 16px;
 font-weight: 700;
 color: #f1f5f9;
 letter-spacing: -0.3px;
}

.brand-subtitle {
 font-size: 12px;
 color: #64748b;
 font-weight: 400;
}

.header-right {
 display: flex;
 align-items: center;
 gap: 8px;
}

.status-dot {
 width: 8px;
 height: 8px;
 border-radius: 50%;
 background: #22c55e;
 animation: pulse-green 2s infinite;
}

@keyframes pulse-green {
 0%, 100% {
 box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.5);
 }
 50% {
 box-shadow: 0 0 0 6px rgba(34, 197, 94, 0);
 }
}

.status-text {
 font-size: 12px;
 color: #22c55e;
 font-weight: 500;
}

/* === Messages Area === */
.messages-area {
 flex: 1;
 overflow-y: auto;
 padding: 24px;
 display: flex;
 flex-direction: column;
 gap: 16px;
 scrollbar-width: thin;
 scrollbar-color: #1e293b transparent;
}

.messages-area::-webkit-scrollbar {
 width: 6px;
}

.messages-area::-webkit-scrollbar-track {
 background: transparent;
}

.messages-area::-webkit-scrollbar-thumb {
 background: #1e293b;
 border-radius: 3px;
}

/* === Message Rows === */
.message-row {
 display: flex;
 align-items: flex-start;
 gap: 10px;
 max-width: 85%;
 animation: fadeIn 0.3s ease;
}

.message-row.user {
 align-self: flex-end;
 flex-direction: row-reverse;
}

.message-row.assistant {
 align-self: flex-start;
}

@keyframes fadeIn {
 from {
 opacity: 0;
 transform: translateY(8px);
 }
 to {
 opacity: 1;
 transform: translateY(0);
 }
}

/* === Message Avatar === */
.message-avatar {
 width: 28px;
 height: 28px;
 border-radius: 8px;
 background: linear-gradient(135deg, #06b6d4, #0891b2);
 display: flex;
 align-items: center;
 justify-content: center;
 flex-shrink: 0;
 font-size: 12px;
 color: #fff;
 margin-top: 2px;
}

/* === Message Bubbles === */
.message-bubble {
 padding: 12px 16px;
 border-radius: 16px;
 max-width: 100%;
 word-wrap: break-word;
}

.message-bubble.user {
 background: #1e293b;
 border: 1px solid #334155;
 border-bottom-right-radius: 4px;
 color: #f1f5f9;
}

.message-bubble.assistant {
 background: transparent;
 border-bottom-left-radius: 4px;
 color: #e2e8f0;
}

.message-text {
 font-size: 14px;
 line-height: 1.6;
}

.message-text strong {
 color: #f8fafc;
 font-weight: 600;
}

/* === Confirmation Card === */
.confirmation-card {
 margin-top: 12px;
 padding: 12px 16px;
 background: rgba(6, 182, 212, 0.08);
 border: 1px solid rgba(6, 182, 212, 0.25);
 border-radius: 10px;
}

.confirmation-badge {
 display: flex;
 align-items: center;
 gap: 8px;
}

.badge-icon {
 width: 22px;
 height: 22px;
 border-radius: 50%;
 background: #06b6d4;
 color: #fff;
 display: flex;
 align-items: center;
 justify-content: center;
 font-size: 12px;
 font-weight: bold;
}

.badge-text {
 font-size: 14px;
 font-weight: 600;
 color: #06b6d4;
 font-family: 'SF Mono', 'Fira Code', monospace;
}

/* === Chips === */
.chips-container {
 display: flex;
 flex-wrap: wrap;
 gap: 8px;
 margin-top: 12px;
}

.chip {
 padding: 6px 14px;
 border-radius: 20px;
 border: 1px solid #334155;
 background: transparent;
 color: #94a3b8;
 font-size: 13px;
 cursor: pointer;
 transition: all 0.2s ease;
 font-family: inherit;
}

.chip:hover {
 border-color: #06b6d4;
 color: #06b6d4;
 background: rgba(6, 182, 212, 0.08);
}

.chip:active {
 transform: scale(0.96);
}

/* === Action Cards === */
.action-cards-container {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
 gap: 10px;
 margin-top: 14px;
}

.action-card {
 display: flex;
 align-items: center;
 gap: 12px;
 padding: 14px 16px;
 background: #111827;
 border: 1px solid #1e293b;
 border-radius: 12px;
 cursor: pointer;
 transition: all 0.2s ease;
 text-align: left;
 font-family: inherit;
 color: inherit;
}

.action-card:hover {
 border-color: #06b6d4;
 background: #0f1a2b;
 transform: translateY(-1px);
 box-shadow: 0 4px 12px rgba(6, 182, 212, 0.1);
}

.action-card:active {
 transform: translateY(0);
}

.action-card-icon {
 font-size: 22px;
 flex-shrink: 0;
}

.action-card-content {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.action-card-title {
 font-size: 13px;
 font-weight: 600;
 color: #f1f5f9;
}

.action-card-desc {
 font-size: 11px;
 color: #64748b;
}

/* === Input Bar === */
.input-bar {
 padding: 16px 24px;
 background: #0d1117;
 border-top: 1px solid #1e293b;
 flex-shrink: 0;
}

.input-wrapper {
 display: flex;
 align-items: center;
 gap: 10px;
 background: #111827;
 border: 1px solid #1e293b;
 border-radius: 12px;
 padding: 4px 4px 4px 16px;
 transition: border-color 0.2s ease;
}

.input-wrapper:focus-within {
 border-color: #06b6d4;
 box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.1);
}

.message-input {
 flex: 1;
 background: transparent;
 border: none;
 outline: none;
 color: #f1f5f9;
 font-size: 14px;
 font-family: inherit;
 padding: 10px 0;
}

.message-input::placeholder {
 color: #475569;
}

.message-input:disabled {
 opacity: 0.5;
}

.send-button {
 width: 38px;
 height: 38px;
 border-radius: 10px;
 border: none;
 background: #06b6d4;
 color: #fff;
 display: flex;
 align-items: center;
 justify-content: center;
 cursor: pointer;
 transition: all 0.2s ease;
 flex-shrink: 0;
}

.send-button:hover:not(:disabled) {
 background: #0891b2;
 transform: scale(1.05);
}

.send-button:active:not(:disabled) {
 transform: scale(0.95);
}

.send-button:disabled {
 opacity: 0.3;
 cursor: not-allowed;
}

/* === Typing Indicator === */
.typing-indicator {
 display: flex;
 align-items: center;
 gap: 4px;
 padding: 4px 0;
}

.typing-indicator .dot {
 width: 7px;
 height: 7px;
 border-radius: 50%;
 background: #475569;
 animation: bounce 1.4s infinite ease-in-out;
}

.typing-indicator .dot:nth-child(1) {
 animation-delay: 0s;
}

.typing-indicator .dot:nth-child(2) {
 animation-delay: 0.2s;
}

.typing-indicator .dot:nth-child(3) {
 animation-delay: 0.4s;
}

@keyframes bounce {
 0%, 60%, 100% {
 transform: translateY(0);
 }
 30% {
 transform: translateY(-6px);
 }
}

/* === Submitting Indicator === */
.submitting-indicator {
 display: flex;
 align-items: center;
 gap: 10px;
 color: #94a3b8;
 font-size: 13px;
}

.spinner {
 width: 16px;
 height: 16px;
 border: 2px solid #1e293b;
 border-top-color: #06b6d4;
 border-radius: 50%;
 animation: spin 0.8s linear infinite;
}

@keyframes spin {
 to {
 transform: rotate(360deg);
 }
}

/* === Responsive === */
@media (max-width: 600px) {
 .assistant-header {
 padding: 12px 16px;
 }

 .messages-area {
 padding: 16px;
 }

 .input-bar {
 padding: 12px 16px;
 }

 .message-row {
 max-width: 95%;
 }

 .action-cards-container {
 grid-template-columns: 1fr;
 }
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","/**
